1	import { ok, fail } from './result.js';
2	import { roundCents } from './money.js';
3	import { getCustomer, normalizeId, TIER_DISCOUNTS } from './customers.js';
4	import { getProduct } from './catalogue.js';
5	import { nextInvoiceNumber } from './numbering.js';
6	import { isValidDate } from './dates.js';
7	
8	/**
9	 * Create an invoice.
10	 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number, discountPercent?: number }> }}
11	 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array } } | { ok: false, error: string }}
12	 */
13	export function createInvoice({ customerId, issueDate, lines }) {
14	  // Normalize customer ID
15	  const normalizedCustomerId = normalizeId(customerId);
16	
17	  // Validate customer exists
18	  const customerResult = getCustomer(normalizedCustomerId);
19	  if (!customerResult.ok) {
20	    return customerResult;
21	  }
22	
23	  const customer = customerResult.value;
24	
25	  // Validate issue date format and validity
26	  if (!isValidDate(issueDate)) {
27	    return fail('DATE_INVALID');
28	  }
29	
30	  // Validate lines is not empty
31	  if (!lines || lines.length === 0) {
32	    return fail('NO_LINES');
33	  }
34	
35	  // Build and validate invoice lines
36	  const invoiceLines = [];
37	  for (const line of lines) {
38	    // Validate qty
39	    if (!Number.isInteger(line.qty) || line.qty <= 0) {
40	      return fail('QTY_INVALID');
41	    }
42	
43	    // Determine discount: explicit discountPercent wins, otherwise use tier discount
44	    const discountPercent = line.discountPercent !== undefined ? line.discountPercent : TIER_DISCOUNTS[customer.tier];
45	
46	    // Validate discountPercent
47	    if (typeof discountPercent !== 'number' || discountPercent < 0 || discountPercent > 100) {
48	      return fail('DISCOUNT_INVALID');
49	    }
50	
51	    // Look up product
52	    const productResult = getProduct(line.sku);
53	    if (!productResult.ok) {
54	      return productResult;
55	    }
56	
57	    const product = productResult.value;
58	    invoiceLines.push({
59	      sku: line.sku,
60	      name: product.name,
61	      qty: line.qty,
62	      unitPrice: product.unitPrice,
63	      vatRate: product.vatRate,
64	      discountPercent,
65	    });
66	  }
67	
68	  return ok({
69	    customerId: normalizedCustomerId,
70	    issueDate,
71	    status: 'draft',
72	    lines: invoiceLines,
73	  });
74	}
75	
76	/**
77	 * Calculate the total for one line: qty times unitPrice.
78	 * @param {{ qty: number, unitPrice: number }}
79	 * @returns {number} Total in cents
80	 */
81	export function lineTotal(line) {
82	  return roundCents(line.qty * line.unitPrice);
83	}
84	
85	/**
86	 * Calculate the discount for one line: lineTotal times discountPercent / 100.
87	 * @param {{ qty: number, unitPrice: number, discountPercent?: number }}
88	 * @returns {number} Discount in cents
89	 */
90	export function lineDiscount(line) {
91	  const total = lineTotal(line);
92	  const discountPercent = line.discountPercent ?? 0;
93	  const discount = roundCents(total * discountPercent / 100);
94	  return Math.max(0, discount);
95	}
96	
97	/**
98	 * Calculate VAT for one line: (lineTotal - lineDiscount) times vatRate / 100.
99	 * @param {{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }}
100	 * @returns {number} VAT in cents
101	 */
102	export function lineVAT(line) {
103	  const total = lineTotal(line);
104	  const discount = lineDiscount(line);
105	  const amountAfterDiscount = Math.max(0, total - discount);
106	  const vatRate = line.vatRate ?? 0;
107	  const vat = roundCents(amountAfterDiscount * vatRate / 100);
108	  return Math.max(0, vat);
109	}
110	
111	/**
112	 * Calculate totals for an invoice.
113	 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }> }}
114	 * @returns {{ subtotal: number, discount: number, vat: number, total: number }} Amounts in cents
115	 */
116	export function invoiceTotals(invoice) {
117	  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
118	  const discount = invoice.lines.reduce((sum, line) => sum + lineDiscount(line), 0);
119	  const vat = invoice.lines.reduce((sum, line) => sum + lineVAT(line), 0);
120	  const total = Math.max(0, subtotal - discount + vat);
121	  return {
122	    subtotal,
123	    discount,
124	    vat,
125	    total,
126	  };
127	}
128	
129	/**
130	 * Add or update a line on an invoice.
131	 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }} invoice
132	 * @param {{ sku: string, qty: number, discountPercent?: number }}
133	 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array } } | { ok: false, error: string }}
134	 */
135	export function addLine(invoice, { sku, qty, discountPercent }) {
136	  // Check status is draft
137	  if (invoice.status !== 'draft') {
138	    return fail('NOT_DRAFT');
139	  }
140	
141	  // Validate qty
142	  if (!Number.isInteger(qty) || qty <= 0) {
143	    return fail('QTY_INVALID');
144	  }
145	
146	  // Validate discountPercent
147	  const discount = discountPercent ?? 0;
148	  if (typeof discount !== 'number' || discount < 0 || discount > 100) {
149	    return fail('DISCOUNT_INVALID');
150	  }
151	
152	  // Look up product
153	  const productResult = getProduct(sku);
154	  if (!productResult.ok) {
155	    return productResult;
156	  }
157	
158	  const product = productResult.value;
159	
160	  // Create new lines array
161	  const newLines = invoice.lines.map((line) => ({ ...line }));
162	
163	  // Check if SKU already exists
164	  const existingLineIndex = newLines.findIndex((line) => line.sku === sku);
165	
166	  if (existingLineIndex !== -1) {
167	    // Update existing line's qty
168	    newLines[existingLineIndex] = {
169	      ...newLines[existingLineIndex],
170	      qty: newLines[existingLineIndex].qty + qty,
171	    };
172	  } else {
173	    // Add new line
174	    newLines.push({
175	      sku,
176	      name: product.name,
177	      qty,
178	      unitPrice: product.unitPrice,
179	      vatRate: product.vatRate,
180	      discountPercent: discount,
181	    });
182	  }
183	
184	  return ok({
185	    customerId: invoice.customerId,
186	    issueDate: invoice.issueDate,
187	    status: invoice.status,
188	    lines: newLines,
189	  });
190	}
191	
192	/**
193	 * Remove a line from an invoice.
194	 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }}
195	 * @param {string} sku
196	 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array } } | { ok: false, error: string }}
197	 */
198	export function removeLine(invoice, sku) {
199	  // Check status is draft
200	  if (invoice.status !== 'draft') {
201	    return fail('NOT_DRAFT');
202	  }
203	
204	  // Find the line to remove
205	  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
206	
207	  if (lineIndex === -1) {
208	    return fail('LINE_NOT_FOUND');
209	  }
210	
211	  // Check if this is the last line
212	  if (invoice.lines.length === 1) {
213	    return fail('NO_LINES');
214	  }
215	
216	  // Create new lines array without the removed line
217	  const newLines = invoice.lines.filter((line) => line.sku !== sku);
218	
219	  return ok({
220	    customerId: invoice.customerId,
221	    issueDate: invoice.issueDate,
222	    status: invoice.status,
223	    lines: newLines,
224	  });
225	}
226	
227	/**
228	 * Issue a draft invoice, assigning it a number and changing status to 'issued'.
229	 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }} invoice
230	 * @param {Array<string>} existingNumbers - Invoice numbers already issued
231	 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, number: string, lines: Array } } | { ok: false, error: string }}
232	 */
233	export function issueInvoice(invoice, existingNumbers) {
234	  // Check status is draft
235	  if (invoice.status !== 'draft') {
236	    return fail('NOT_DRAFT');
237	  }
238	
239	  // Generate next invoice number
240	  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);
241	
242	  return ok({
243	    customerId: invoice.customerId,
